                    "ElementsAdded" -> ElementsAdded(ids = field(data, "ids", ListSerializer(String.serializer())))
                    "ElementsDeleted" -> ElementsDeleted(ids = field(data, "ids", ListSerializer(String.serializer())))
                    "ElementsUpdated" -> ElementsUpdated(ids = field(data, "ids", ListSerializer(String.serializer())))
                    "LayerReordered" -> LayerReordered
                    "MemberJoined" -> MemberJoined(member = field(data, "member", String.serializer()))
                    "MemberUsernameUpdated" -> MemberUsernameUpdated(member = field(data, "member", String.serializer()))
                    "OwnerTransferred" -> OwnerTransferred(member = field(data, "member", String.serializer()))
                    "RoleUpdated" -> RoleUpdated(member = field(data, "member", String.serializer()))
                    else -> Unknown(kind, data)
                }
        }
    }

    /** One frame of [events]: the event's log position (`index:seq`) and the event. */
    data class EventFrame(
